'use strict';
function readerStore(){structure();st.lab.reader??={drafts:{},answers:{},scores:{},visited:{},last:{ch:1,page:0}};for(const k of ['drafts','answers','scores','visited'])st.lab.reader[k]??={};return st.lab.reader}
function readerStop(){const p=document.querySelector('#readerPlayer');if(p){p.pause();p.removeAttribute('src');p.load()}}
function readingRoom(ch=0,page=0){readerStop();document.activeElement?.blur?.();const rs=readerStore();if(!ch){app.innerHTML='<div class=navline><button id=readerHome>رجع للتدريب</button><span class=cap>LESEN + HÖREN</span></div><section class=hero><h1>مكتبة القراءة والاستماع</h1><p>الكتاب مكتوب • التسجيلات الأصلية • فهم وكتابة وحفظ</p><p>سمع بلا نص، قرا وأنت كتسمع، ومن بعد عاود حكي المعنى بكلامك.</p></section>'+(rs.last?.ch?'<button id=readerContinue class=gold>كمل من آخر بلاصة • Kapitel '+rs.last.ch+(rs.last.page?' · Seite '+rs.last.page:'')+'</button>':'')+'<div class=stats><span>12 فصل</span><span>123 تسجيل مربوط بصفحتو</span><span>36 سؤال فهم جديد</span></div><div class=chaptergrid>'+READER_LESSONS.map(l=>'<button class=chapter data-rc='+l.ch+'><em>Kapitel '+l.ch+'</em><h3 dir=ltr>'+esc(COURSE[l.ch-1][0])+'</h3><small>'+READER_PAGES.filter(x=>x.ch===l.ch).length+' صفحات صوتية · '+(rs.scores['f'+l.ch]!==undefined?'آخر فهم: '+rs.scores['f'+l.ch]+'/3':'الفهم باقي ما تجرّبش')+'</small></button>').join('')+'</div><section class=card><p>12 نص/لائحة مختارين ومراجعين، ومعاهم أرشيف مكتوب ديال 89 صفحة مرتبطة بالأوديو. الأرشيف فيه حتى التعليمات وفراغات التمارين المطبوعة؛ ماشي تفريغ كامل للتسجيلات اللي ما عندهاش نص مطبوع. النص المستخرج آلياً يقدر يبقى فيه خطأ مطبعي، وتقدر تقارنو بصفحة الأصل.</p><p>الأسئلة والعبارات والتداريب الجديدة من إعداد اللعبة، ماشي تصحيح رسمي ديال تمارين الناشر.</p></section>';$('#readerHome').onclick=home;if($('#readerContinue'))$('#readerContinue').onclick=()=>readingRoom(rs.last.ch,rs.last.page);app.querySelectorAll('[data-rc]').forEach(b=>b.onclick=()=>readingRoom(+b.dataset.rc));window.scrollTo(0,0);return}
const l=READER_LESSONS[ch-1];const r=page?READER_PAGES.find(x=>x.page===page&&x.ch===ch):null;if(page&&!r){readingRoom(ch);return}const key=r?'p'+page:'f'+ch;rs.last={ch,page};rs.visited[key]=true;save();const tracks=r?r.tracks:[l.track],text=r?r.text:l.text;
app.innerHTML='<div class=navline><button id=readerIndex>جميع الفصول</button><button id=readerTrain>تدريب الفصل</button></div><section class=hero><span class=cap>Kapitel '+ch+' • '+esc(COURSE[ch-1][0])+'</span><h1 dir=auto>'+esc(r?'نصوص وتمارين الصفحة '+page:l.title)+'</h1><p>'+(r?'نص الصفحة مكتوب. صفحات الأرشيف غير المراجعة تقدر يبقى فيها خطأ فالاستخراج؛ فراغات التمارين بقات كيف مطبوعة.':'نص مختار من الكتاب ومراجع، مع أسئلة فهم جديدة.')+'</p></section><section class="card reader-player"><label>التسجيل الأصلي<select id=readerTrack>'+tracks.map(([d,n])=>'<option value="'+d+'-'+n+'">CD '+d+' · Track '+n+'</option>').join('')+'</select></label><audio id=readerPlayer controls preload=none></audio><div class=reader-tools><button id=readerRewind>↶ 5 ثواني</button><label>السرعة<select id=readerSpeed><option value=.75>0.75×</option><option value=.9>0.9×</option><option value=1 selected>1×</option><option value=1.25>1.25×</option></select></label><button id=readerLoop aria-pressed=false>تكرار: لا</button></div><p id=readerAudioStatus role=status>التشغيل من الزر. غير التسجيل المختار هو اللي كيتحمّل.</p></section><nav class=reader-tabs aria-label="أنشطة القراءة"><button data-rpanel=text aria-pressed=true>النص</button><button data-rpanel=questions aria-pressed=false>الفهم</button><button data-rpanel=writing aria-pressed=false>الكتابة</button><button data-rpanel=phrases aria-pressed=false>الحفظ</button></nav><section class=card data-pane=text><div class=navline><h2>قرا وسمع</h2><button id=readerHide aria-expanded=true>خبي النص</button></div><div id=readerText class=reader-text lang=de dir=ltr>'+text.split(/\n+/).map(x=>hulpLine(x)).join('')+(r?(r.extra||[]).map(x=>'<details class=reader-continuation><summary>Weitere Inhalte · Seite '+x.page+'</summary>'+x.text.split(/\n+/).map(t=>hulpLine(t)).join('')+'</details>').join(''):'')+'</div><details class=reader-origin><summary>صفحة الأصل للمقارنة</summary><p>الأساس هنا هو النص المكتوب. الصورة اختيارية للمقارنة مع تنسيق الكتاب.</p><a target=_blank rel=noopener href="book-pages/'+(r?page:l.page)+'.jpg">فتح الصفحة '+(r?page:l.page)+'</a></details>'+([5,7,10,11,12].includes(ch)?'<p class=tip>الأرقام والأثمنة والمواعيد هنا ديال طبعة الكتاب؛ استعملها للفهم اللغوي، ماشي كمعلومات محدثة للسفر أو الإحصائيات.</p>':'')+'</section><section class=card data-pane=questions hidden><h2>'+(r?'فهم المسموع والمقروء':'اختبر الفهم • 3 أسئلة')+'</h2><p>جرّب تجاوب بلا النص. الأجوبة الصحيحة كتبان غير من بعد المحاولة.</p><div id=readerQuestions></div><p id=readerResult role=status aria-live=polite></p></section><section class=card data-pane=writing hidden><h2>دابا كتب من راسك</h2><p>'+esc(l.writing)+'</p><label>الفقرة ديالك<textarea id=readerDraft lang=de dir=ltr rows=7 placeholder="Schreib hier …" spellcheck=false></textarea></label><p id=readerDraftStatus role=status></p><button id=readerCopy>نسخ للتصحيح فـChatGPT</button><details><summary>لائحة المراجعة الذاتية</summary><p>جاوبت على جميع النقط؟ الفعل فبلاصتو؟ الأسماء بحروف كبيرة؟ الأدوات والملكية صحيحين؟ قرا الفقرة بصوتك. الكتابة الحرة ما كتتنقّطش آلياً.</p></details></section><section class=card data-pane=phrases hidden>'+readerModelPanel(ch)+'<h2>عبارات الفصل للحفظ والاستعمال</h2><p>هاد العبارات مختارة للتواصل، ماشي لائحة شاملة لكل كلمات الفصل. قرا الجملة بالألمانية، وشوف المعنى ديالها ملي تحتاجو.</p><label><input type=checkbox id=recallFirst> تدرّب من الدارجة للألمانية</label><div id=recallList>'+l.phrases.map(([de,ar])=>hulpCard(de,ar)).join('')+'</div><p class=tip>دير جملة من حياتك بكل عبارة، وردّدها بلا ما تشوف. الصوت فهاد القسم للتسجيل الأصلي، ماشي نطق آلي للعبارات المختارة.</p></section><section class=card><h2>جميع الصفحات الصوتية • Kapitel '+ch+'</h2><p>كل صفحة فيها نصها مكتوب والتسجيلات اللي مربوطين بها. النطق ولوائح الكلمات وتمارين الفراغات داخلين حتى هما.</p><label>قلب فهاد الفصل<input id=readerSearch type=search dir=auto placeholder="كلمة ألمانية أو رقم الصفحة"></label><div class=reader-catalog id=readerCatalog><button data-rpage=0 class="'+(!r?'selected':'')+'">★ النص المختار · '+esc(l.title)+'</button>'+READER_PAGES.filter(x=>x.ch===ch).map(x=>'<button data-rpage='+x.page+' class="'+(page===x.page?'selected':'')+'"><strong>Seite '+x.page+'</strong><small>'+x.tracks.map(([d,n])=>'CD '+d+' / '+n).join(' · ')+'</small></button>').join('')+'</div><p id=readerSearchStatus role=status></p></section>';
const md=$('#modelDraft'),mk='model-'+ch;md.value=rs.drafts[mk]||'';md.oninput=()=>{rs.drafts[mk]=md.value;save()};$('#recallFirst').onchange=e=>{$('#recallList').innerHTML=l.phrases.map(([de,ar])=>e.target.checked?'<details class=phrase-recall><summary>'+esc(ar)+'</summary>'+hulpCard(de,ar)+'</details>':hulpCard(de,ar)).join('')};const player=$('#readerPlayer');function chooseTrack(){player.pause();const [d,n]=$('#readerTrack').value.split('-').map(Number),a=BOOK_AUDIO.find(x=>x.disc===d&&x.n===n);player.src=a.src;player.load();player.playbackRate=+$('#readerSpeed').value}chooseTrack();$('#readerTrack').onchange=chooseTrack;$('#readerSpeed').onchange=e=>player.playbackRate=+e.target.value;$('#readerRewind').onclick=()=>{if(Number.isFinite(player.currentTime))player.currentTime=Math.max(0,player.currentTime-5)};$('#readerLoop').onclick=e=>{player.loop=!player.loop;e.currentTarget.textContent='تكرار: '+(player.loop?'نعم':'لا');e.currentTarget.setAttribute('aria-pressed',String(player.loop))};player.onerror=()=>$('#readerAudioStatus').textContent='تعذّر تحميل التسجيل. تأكد من الإنترنت وعاود جرّب.';
$('#readerIndex').onclick=()=>readingRoom();$('#readerTrain').onclick=()=>{readerStop();chapter(ch)};
app.querySelectorAll('[data-rpanel]').forEach(b=>b.onclick=()=>{app.querySelectorAll('[data-pane]').forEach(p=>p.hidden=p.dataset.pane!==b.dataset.rpanel);app.querySelectorAll('[data-rpanel]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});
$('#readerHide').onclick=e=>{let t=$('#readerText');t.hidden=!t.hidden;e.currentTarget.textContent=t.hidden?'كشف النص':'خبي النص';e.currentTarget.setAttribute('aria-expanded',String(!t.hidden))};
const qa=$('#readerQuestions');if(!r){qa.innerHTML=l.qs.map(([q,...options],i)=>'<fieldset class=reader-question><legend dir=ltr lang=de>'+esc(q)+'</legend>'+shuffle(options.map((v,j)=>({v,correct:j===0}))).map(o=>'<label dir=ltr lang=de><input type=radio name="rq'+i+'" value="'+esc(o.v)+'"> '+esc(o.v)+'</label>').join('')+'</fieldset>').join('')+'<button id=readerGrade class=gold>صحّح أجوبتي</button>';$('#readerGrade').onclick=()=>{const chosen=l.qs.map((_,i)=>app.querySelector('input[name=rq'+i+']:checked'));if(chosen.some(x=>!x)){$('#readerResult').textContent='جاوب على الأسئلة الثلاثة قبل التصحيح.';return}let score=0;chosen.forEach((x,i)=>{const ok=x.value===l.qs[i][1];if(ok)score++;const field=x.closest('fieldset');field.querySelector('.reader-feedback')?.remove();const f=document.createElement('p');f.className='reader-feedback '+(ok?'good':'bad');f.dir='auto';f.textContent=ok?'صحيح ✓':'راجع: '+l.qs[i][1];field.append(f)});rs.scores[key]=score;save();$('#readerResult').textContent='النتيجة: '+score+'/3. رجع للجمل اللي فيها المعلومة وردّدها بصوتك.'}}else{qa.innerHTML='<p>هاد الأسئلة مفتوحة على الصفحة أو التسجيل المختار. ما كاينش تنقيط آلي هنا.</p><ol><li>شنو موضوع النص أو التسجيل؟ جاوب بجملة ألمانية.</li><li>كتب ثلاث معلومات محددة سمعتيهم: أسماء، أماكن، أرقام، أنشطة أو صفات.</li><li>اختار جوج عبارات وردّ عليهم بجمل من حياتك. إلا كان تمرين فراغات، زيد الأجوبة ديالك بالترقيم.</li></ol><label>أجوبة الفهم<textarea id=readerOpenAnswers lang=de dir=ltr rows=6 placeholder="1. …"></textarea></label>';const ans=$('#readerOpenAnswers');ans.value=rs.answers[key]||'';ans.oninput=()=>{rs.answers[key]=ans.value;save()}}
const draft=$('#readerDraft');draft.value=rs.drafts[key]||'';function updateDraft(){rs.drafts[key]=draft.value;save();$('#readerDraftStatus').textContent=(draft.value.trim()?draft.value.trim().split(/\s+/).length:0)+' كلمة · محفوظ فهاد الجهاز. للحفظ فالحساب استعمل الإعدادات.'}draft.oninput=updateDraft;updateDraft();$('#readerCopy').onclick=async()=>{const txt='Kapitel '+ch+' · '+(r?'Seite '+page:l.title)+'\n'+l.writing+'\n\n'+draft.value;try{await navigator.clipboard.writeText(txt);$('#readerCopy').textContent='تنسخ ✓ صيفطو هنا باش نصحّحو'}catch{draft.focus();draft.select();$('#readerCopy').textContent='حدّد النص ونسخو يدوياً'}};
app.querySelectorAll('[data-rpage]').forEach(b=>b.onclick=()=>readingRoom(ch,+b.dataset.rpage));$('#readerSearch').oninput=e=>{const q=e.target.value.trim().toLocaleLowerCase('de');let count=0;app.querySelectorAll('[data-rpage]').forEach(b=>{const n=+b.dataset.rpage,x=n?READER_PAGES.find(x=>x.page===n):l;b.hidden=q&&!String(n+' '+(x.text||'')+' '+b.textContent).toLocaleLowerCase('de').includes(q);if(!b.hidden)count++});$('#readerSearchStatus').textContent=count?'عدد النتائج: '+count:'ما لقيتش هاد الكلمة فهاد الفصل.'};window.scrollTo(0,0)
}
